49	export function deferred() {
50	  let resolve;
51	  let reject;
52	  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
53	  return { promise, resolve, reject };
54	}
55	
56	export function makeReply(status, body, { badJson = false } = {}) {
57	  const reply = {
58	    status,
59	    jsonCalls: 0,
60	    json() {
61	      reply.jsonCalls += 1;
62	      return badJson ? Promise.reject(new SyntaxError('bad json')) : Promise.resolve(body);
63	    },
64	  };
65	  return reply;
66	}
67	
68	export async function flush() {
69	  for (let i = 0; i < 5; i += 1) await new Promise((r) => setImmediate(r));
70	}
71	
72	export function loadPage(appPath) {
73	  const els = Object.fromEntries(IDS.map((id) => [id, new FakeElement('x', id)]));
74	  const calls = [];
75	  const document = {
76	    getElementById: (id) => els[id],
77	    createElement: (tag) => new FakeElement(tag),
78	  };
79	  const fetch = (url, options) => {
80	    const d = deferred();
81	    calls.push({ url, options, reply: (r) => d.resolve(r), fail: (e) => d.reject(e ?? new TypeError('down')) });
82	    return d.promise;
83	  };
84	  const context = vm.createContext({ document, fetch });
85	  vm.runInContext(fs.readFileSync(appPath, 'utf8'), context, { filename: 'app.js' });
86	  return { els, calls };
87	}
